-- Define helper function early to prevent RLS missing function errors
CREATE OR REPLACE FUNCTION get_my_account_id()
RETURNS UUID AS $$
  SELECT account_id FROM public.profiles WHERE id = auth.uid()
$$ LANGUAGE sql SECURITY DEFINER STABLE;

-- Create team_invitations early to prevent RLS errors on missing relation
CREATE TABLE IF NOT EXISTS public.team_invitations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,
    email TEXT NOT NULL,
    role TEXT CHECK (role IN ('admin', 'agent', 'member')) DEFAULT 'agent',
    token TEXT DEFAULT gen_random_uuid()::text,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    status TEXT CHECK (status IN ('pending', 'accepted')) DEFAULT 'pending',
    UNIQUE(account_id, email)
);
  -- FILE: 20240218_add_profile_created_at.sql  -- Add missing created_at column to profiles table ALTER TABLE public.profiles  ADD COLUMN IF NOT EXISTS created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW();  -- Update existing rows to have a created_at value if they don't (though default NOW() handles new rows) UPDATE public.profiles SET created_at = updated_at WHERE created_at IS NULL;   -- FILE: 20240218_fix_profile_delete.sql  -- Allow admins to delete profiles in their account (remove team members) DROP POLICY IF EXISTS "Admins can delete profiles in their account" ON public.profiles; CREATE POLICY "Admins can delete profiles in their account" ON public.profiles FOR DELETE USING (     account_id = get_my_account_id()     AND (get_my_account_id() IS NOT NULL)     AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin'     AND id != auth.uid() -- Protect self-deletion here too for extra safety );   -- FILE: 20240218_fix_rls.sql  -- Allow users to view profiles that belong to the same account DROP POLICY IF EXISTS "Users can view profiles in their account" ON public.profiles; CREATE POLICY "Users can view profiles in their account" ON public.profiles FOR SELECT USING (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid()     ) );  -- Note: The previous "Users can view their own account" policy on accounts table is likely preventing  -- access if not correctly set up, but let's assume accounts table is fine. -- If the user sees "Active Members (0)", it means they can't see even themselves IF the query does filtering. -- Or they see themselves but the array mapping fails? No.  -- Let's also ensure invitations are visible DROP POLICY IF EXISTS "Admins can view invitations for their account" ON public.team_invitations; CREATE POLICY "Admins can view invitations for their account" ON public.team_invitations FOR SELECT USING (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid() AND role = 'admin'     ) );  -- Ensure admins can delete invitations (fix for removeTeamMember) DROP POLICY IF EXISTS "Admins can delete invitations for their account" ON public.team_invitations; CREATE POLICY "Admins can delete invitations for their account" ON public.team_invitations FOR DELETE USING (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid() AND role = 'admin'     ) );   -- FILE: 20240218_fix_rls_recursion.sql  -- Helper function to get current user's account ID securely -- This breaks the infinite recursion by using SECURITY DEFINER CREATE OR REPLACE FUNCTION get_my_account_id() RETURNS UUID AS $$   SELECT account_id FROM public.profiles WHERE id = auth.uid() $$ LANGUAGE sql SECURITY DEFINER STABLE;  -- Drop existing problematic policies DROP POLICY IF EXISTS "Users can view profiles in their account" ON public.profiles; DROP POLICY IF EXISTS "Users can view own profile" ON public.profiles; DROP POLICY IF EXISTS "Users can view team members" ON public.profiles;  -- 1. Allow users to view their OWN profile (Critical for getting account_id initially) CREATE POLICY "Users can view own profile" ON public.profiles FOR SELECT USING (auth.uid() = id);  -- 2. Allow users to view other profiles in the same account using the helper function CREATE POLICY "Users can view team members" ON public.profiles FOR SELECT USING (     account_id = get_my_account_id() );  -- Fix team_invitations policies to use the helper function as well DROP POLICY IF EXISTS "Admins can view invitations for their account" ON public.team_invitations; DROP POLICY IF EXISTS "Admins can view invitations" ON public.team_invitations;  CREATE POLICY "Admins can view invitations" ON public.team_invitations FOR SELECT USING (     account_id = get_my_account_id()     AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin' );  DROP POLICY IF EXISTS "Admins can create invitations for their account" ON public.team_invitations; DROP POLICY IF EXISTS "Admins can insert invitations" ON public.team_invitations;  CREATE POLICY "Admins can insert invitations" ON public.team_invitations FOR INSERT WITH CHECK (     account_id = get_my_account_id()     AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin' );  DROP POLICY IF EXISTS "Admins can delete invitations for their account" ON public.team_invitations; DROP POLICY IF EXISTS "Admins can delete invitations" ON public.team_invitations;  CREATE POLICY "Admins can delete invitations" ON public.team_invitations FOR DELETE USING (     account_id = get_my_account_id()     AND (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin' );   -- FILE: 20240218_fix_roles.sql  -- Fix profiles table role constraint to match application roles ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check;  -- Add updated constraint allowing admin, agent, member (and keeping sales_rep for safety) ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check  CHECK (role IN ('admin', 'agent', 'member', 'sales_rep'));   -- FILE: 20240218_team_invitations.sql  -- Create team_invitations table CREATE TABLE IF NOT EXISTS public.team_invitations (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     email TEXT NOT NULL,     role TEXT CHECK (role IN ('admin', 'agent', 'member')) DEFAULT 'agent',     token TEXT DEFAULT gen_random_uuid()::text,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     status TEXT CHECK (status IN ('pending', 'accepted')) DEFAULT 'pending',     UNIQUE(account_id, email) );  -- Enable RLS ALTER TABLE public.team_invitations ENABLE ROW LEVEL SECURITY;  -- RLS Policies for team_invitations CREATE POLICY "Admins can view invitations for their account" ON public.team_invitations FOR SELECT USING (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid() AND role = 'admin'     ) );  CREATE POLICY "Admins can insert invitations for their account" ON public.team_invitations FOR INSERT WITH CHECK (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid() AND role = 'admin'     ) );  CREATE POLICY "Admins can delete invitations for their account" ON public.team_invitations FOR DELETE USING (     account_id IN (         SELECT account_id FROM public.profiles          WHERE id = auth.uid() AND role = 'admin'     ) );  -- Function to handle new user signup and link to account if invited CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER AS $$ DECLARE     invitation_record record;     new_account_id uuid; BEGIN     -- Check if there is a pending invitation for this email     SELECT * INTO invitation_record      FROM public.team_invitations      WHERE email = NEW.email      AND status = 'pending'     LIMIT 1;      IF invitation_record IS NOT NULL THEN         -- Link new profile to the account         INSERT INTO public.profiles (id, account_id, full_name, role)         VALUES (             NEW.id,              invitation_record.account_id,              COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),             invitation_record.role         );          -- Update invitation status         UPDATE public.team_invitations          SET status = 'accepted'          WHERE id = invitation_record.id;     ELSE         -- Create new account for non-invited user         INSERT INTO public.accounts (name, subscription_status)         VALUES (             COALESCE(NEW.raw_user_meta_data->>'company_name', 'My Company'),             'trialing'         )         RETURNING id INTO new_account_id;          -- Create admin profile linked to new account         INSERT INTO public.profiles (id, account_id, full_name, role)         VALUES (             NEW.id,              new_account_id,              COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),             'admin'         );     END IF;      RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;  -- Trigger to call handle_new_user on auth.users insert DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();   -- FILE: 20240219_add_profile_columns.sql  -- Migration: Add missing profile columns and notification preferences -- Date: 2024-02-19  ALTER TABLE public.profiles  ADD COLUMN IF NOT EXISTS first_name TEXT, ADD COLUMN IF NOT EXISTS last_name TEXT, ADD COLUMN IF NOT EXISTS phone TEXT, ADD COLUMN IF NOT EXISTS email_alerts BOOLEAN DEFAULT TRUE, ADD COLUMN IF NOT EXISTS push_notifications BOOLEAN DEFAULT TRUE, ADD COLUMN IF NOT EXISTS sms_updates BOOLEAN DEFAULT FALSE, ADD COLUMN IF NOT EXISTS language TEXT DEFAULT 'en-US';  -- Update full_name check trigger if needed, but usually we handle this in app logic   -- FILE: 20240220_create_widgets.sql  -- Create widgets table CREATE TABLE IF NOT EXISTS public.widgets (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     name TEXT DEFAULT 'WhatsApp Widget',     is_active BOOLEAN DEFAULT true,     config JSONB DEFAULT '{         "phone": "",         "message": "Hello, I am interested in your services.",         "button_text": "Chat with us",         "position": "bottom-right",         "color": "#25D366",         "bubble_text": "Need help?"     }'::jsonb,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     UNIQUE(account_id) -- One widget per account for now );  -- Enable Row Level Security ALTER TABLE public.widgets ENABLE ROW LEVEL SECURITY;  -- RLS Policies CREATE POLICY "Users can view their own widgets" ON public.widgets     FOR SELECT USING (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  CREATE POLICY "Users can insert their own widgets" ON public.widgets     FOR INSERT WITH CHECK (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  CREATE POLICY "Users can update their own widgets" ON public.widgets     FOR UPDATE USING (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  CREATE POLICY "Users can delete their own widgets" ON public.widgets     FOR DELETE USING (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  -- Public can view widgets by ID (for the script) CREATE POLICY "Public can view active widgets by ID" ON public.widgets     FOR SELECT USING (is_active = true);  -- Trigger for updated_at CREATE TRIGGER update_widgets_updated_at BEFORE UPDATE ON public.widgets FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();   -- FILE: 20240221_feature_updates.sql  -- Feature updates for global scaling (RBAC, Webhooks)  -- 1. Update RBAC roles ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_role_check; ALTER TABLE public.profiles ADD CONSTRAINT profiles_role_check  CHECK (role IN ('admin', 'manager', 'sales_rep', 'viewer', 'agent', 'member'));  -- 2. Create Webhooks table CREATE TABLE IF NOT EXISTS public.webhooks (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     url TEXT NOT NULL,     events TEXT[] NOT NULL, -- e.g. ['lead.created', 'meeting.booked']     secret TEXT NOT NULL,     status TEXT DEFAULT 'active' CHECK (status IN ('active', 'inactive')),     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  -- Enable RLS for Webhooks ALTER TABLE public.webhooks ENABLE ROW LEVEL SECURITY;  CREATE POLICY "Users can view their own webhooks" ON public.webhooks FOR SELECT USING (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  CREATE POLICY "Users can manage their own webhooks" ON public.webhooks FOR ALL USING (account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid()));  -- 3. Create Webhook Logs table (for debugging) CREATE TABLE IF NOT EXISTS public.webhook_logs (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     webhook_id UUID NOT NULL REFERENCES public.webhooks(id) ON DELETE CASCADE,     event TEXT NOT NULL,     payload JSONB NOT NULL,     response_status INTEGER,     response_body TEXT,     error TEXT,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  ALTER TABLE public.webhook_logs ENABLE ROW LEVEL SECURITY;  CREATE POLICY "Users can view their own webhook logs" ON public.webhook_logs FOR SELECT USING (webhook_id IN (SELECT id FROM public.webhooks WHERE account_id IN (SELECT account_id FROM public.profiles WHERE id = auth.uid())));   -- FILE: 20240222_security_hardening.sql  -- 1. Leads Table Hardening: Add Unique Constraint for account_id and email -- This prevents duplicate leads for the same email within the same account DO $$  BEGIN      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'leads_account_id_email_key') THEN         ALTER TABLE public.leads ADD CONSTRAINT leads_account_id_email_key UNIQUE (account_id, email);     END IF; END $$;  -- 2. Ensure RLS is enabled for all critical tables ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY; ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY; ALTER TABLE public.meetings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.integrations ENABLE ROW LEVEL SECURITY;  -- 3. RLS Policies for LEADS (Account Isolation) DROP POLICY IF EXISTS "Leads: Account Isolation (Select)" ON public.leads; CREATE POLICY "Leads: Account Isolation (Select)" ON public.leads     FOR SELECT USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Leads: Account Isolation (Insert)" ON public.leads; CREATE POLICY "Leads: Account Isolation (Insert)" ON public.leads     FOR INSERT WITH CHECK (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Leads: Account Isolation (Update)" ON public.leads; CREATE POLICY "Leads: Account Isolation (Update)" ON public.leads     FOR UPDATE USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Leads: Account Isolation (Delete)" ON public.leads; CREATE POLICY "Leads: Account Isolation (Delete)" ON public.leads     FOR DELETE USING (account_id = get_my_account_id());  -- 4. RLS Policies for CONVERSATIONS DROP POLICY IF EXISTS "Conversations: Account Isolation (Select)" ON public.conversations; CREATE POLICY "Conversations: Account Isolation (Select)" ON public.conversations     FOR SELECT USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Conversations: Account Isolation (Insert)" ON public.conversations; CREATE POLICY "Conversations: Account Isolation (Insert)" ON public.conversations     FOR INSERT WITH CHECK (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Conversations: Account Isolation (Update)" ON public.conversations; CREATE POLICY "Conversations: Account Isolation (Update)" ON public.conversations     FOR UPDATE USING (account_id = get_my_account_id());  -- 5. RLS Policies for MESSAGES (Inherited via Conversation) -- Messages don't have account_id directly, we check through conversation DROP POLICY IF EXISTS "Messages: Conversation Isolation (Select)" ON public.messages; CREATE POLICY "Messages: Conversation Isolation (Select)" ON public.messages     FOR SELECT USING (         EXISTS (             SELECT 1 FROM public.conversations             WHERE conversations.id = messages.conversation_id             AND conversations.account_id = get_my_account_id()         )     );  DROP POLICY IF EXISTS "Messages: Conversation Isolation (Insert)" ON public.messages; CREATE POLICY "Messages: Conversation Isolation (Insert)" ON public.messages     FOR INSERT WITH CHECK (         EXISTS (             SELECT 1 FROM public.conversations             WHERE conversations.id = messages.conversation_id             AND conversations.account_id = get_my_account_id()         )     );  -- 6. RLS Policies for MEETINGS DROP POLICY IF EXISTS "Meetings: Account Isolation (Select)" ON public.meetings; CREATE POLICY "Meetings: Account Isolation (Select)" ON public.meetings     FOR SELECT USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Meetings: Account Isolation (Insert)" ON public.meetings; CREATE POLICY "Meetings: Account Isolation (Insert)" ON public.meetings     FOR INSERT WITH CHECK (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Meetings: Account Isolation (Update)" ON public.meetings; CREATE POLICY "Meetings: Account Isolation (Update)" ON public.meetings     FOR UPDATE USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Meetings: Account Isolation (Delete)" ON public.meetings; CREATE POLICY "Meetings: Account Isolation (Delete)" ON public.meetings     FOR DELETE USING (account_id = get_my_account_id());  -- 7. RLS Policies for INTEGRATIONS DROP POLICY IF EXISTS "Integrations: Account Isolation (Select)" ON public.integrations; CREATE POLICY "Integrations: Account Isolation (Select)" ON public.integrations     FOR SELECT USING (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Integrations: Account Isolation (Insert)" ON public.integrations; CREATE POLICY "Integrations: Account Isolation (Insert)" ON public.integrations     FOR INSERT WITH CHECK (account_id = get_my_account_id());  DROP POLICY IF EXISTS "Integrations: Account Isolation (Update)" ON public.integrations; CREATE POLICY "Integrations: Account Isolation (Update)" ON public.integrations     FOR UPDATE USING (account_id = get_my_account_id());  -- 8. Storage RLS (Basic Auth Check for avatar bucket) -- Note: Assuming storage setup via SQL is supported or just documenting the policy -- Most Supabase Storage policies are handled in the storage schema CREATE POLICY "Users can only upload their own avatars" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'profiles' AND auth.uid()::text = (storage.foldername(name))[1]);  CREATE POLICY "Avatar visibility is public" ON storage.objects FOR SELECT TO public USING (bucket_id = 'profiles');   -- FILE: 20240224_add_sequence_metrics.sql  -- Add metrics column to sequences table ALTER TABLE public.sequences  ADD COLUMN IF NOT EXISTS metrics JSONB DEFAULT '{   "enrolled": 0,   "active": 0,   "completed": 0,   "email": {     "sent": 0,     "opened": 0,     "replied": 0   },   "whatsapp": {     "sent": 0,     "opened": 0,     "replied": 0   } }'::jsonb;  -- Comment for clarity COMMENT ON COLUMN public.sequences.metrics IS 'Aggregated analytics for the sequence enrollment and message performance.';   -- FILE: 20240225_add_social_channels.sql  -- Update the check constraint on conversations table for channel ALTER TABLE public.conversations DROP CONSTRAINT IF EXISTS conversations_channel_check; ALTER TABLE public.conversations ADD CONSTRAINT conversations_channel_check  CHECK (channel IN ('whatsapp', 'email', 'widget', 'instagram', 'tiktok'));  -- Comment for clarity COMMENT ON COLUMN public.conversations.channel IS 'Communication channel used for this conversation. Added instagram and tiktok.';   -- FILE: 20240226_support_tickets.sql  -- Create tickets table CREATE TABLE IF NOT EXISTS public.tickets (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     created_at TIMESTAMPTZ DEFAULT now(),     updated_at TIMESTAMPTZ DEFAULT now(),     user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,     subject TEXT NOT NULL,     description TEXT,     status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'resolved', 'closed')),     priority TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'urgent')) );  -- Create ticket_messages table CREATE TABLE IF NOT EXISTS public.ticket_messages (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     ticket_id UUID NOT NULL REFERENCES public.tickets(id) ON DELETE CASCADE,     user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,     message TEXT NOT NULL,     created_at TIMESTAMPTZ DEFAULT now(),     is_admin_reply BOOLEAN DEFAULT false );  -- Enable RLS ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.ticket_messages ENABLE ROW LEVEL SECURITY;  -- Tickets Policies -- Users can view their own tickets CREATE POLICY "Users can view their own tickets" ON public.tickets FOR SELECT USING (auth.uid() = user_id OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin');  -- Users can insert their own tickets CREATE POLICY "Users can insert their own tickets" ON public.tickets FOR INSERT WITH CHECK (auth.uid() = user_id);  -- Admins can update tickets (status, etc) CREATE POLICY "Admins can update tickets" ON public.tickets FOR UPDATE USING ((SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin');  -- Ticket Messages Policies -- Users can view messages for their tickets CREATE POLICY "Users can view messages for their tickets" ON public.ticket_messages FOR SELECT USING (     EXISTS (         SELECT 1 FROM public.tickets         WHERE tickets.id = ticket_messages.ticket_id         AND (tickets.user_id = auth.uid() OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin')     ) );  -- Users can insert messages for their tickets CREATE POLICY "Users can insert messages to their own tickets" ON public.ticket_messages FOR INSERT WITH CHECK (     EXISTS (         SELECT 1 FROM public.tickets         WHERE tickets.id = ticket_id         AND tickets.user_id = auth.uid()     ) OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin' );  -- Create simple trigger for updated_at CREATE OR REPLACE FUNCTION public.handle_updated_at() RETURNS TRIGGER AS $$ BEGIN     NEW.updated_at = now();     RETURN NEW; END; $$ LANGUAGE plpgsql;  CREATE TRIGGER set_tickets_updated_at     BEFORE UPDATE ON public.tickets     FOR EACH ROW     EXECUTE FUNCTION public.handle_updated_at();   -- FILE: 20240227_b2b_database.sql  -- Migration: Create B2B Database tables and structure -- Date: 2024-02-27  -- 1. Add credits to profiles ALTER TABLE public.profiles  ADD COLUMN IF NOT EXISTS b2b_credits INTEGER DEFAULT 150;  -- 2. Create b2b_companies table CREATE TABLE IF NOT EXISTS public.b2b_companies (     id UUID DEFAULT gen_random_uuid() PRIMARY KEY,     name TEXT NOT NULL,     domain TEXT,     logo_url TEXT,     description TEXT,     hq_location TEXT,     industry TEXT,     size TEXT, -- '1-10', '11-50', '51-200', '201-500', '501-1000', '1001-5000', '5001-10000', '10001+'     company_type TEXT,     keywords TEXT[],     founded_year INTEGER,     technologies TEXT[],     funding_amount TEXT,     created_at TIMESTAMPTZ DEFAULT NOW(),     updated_at TIMESTAMPTZ DEFAULT NOW() );  -- Full text search indexing CREATE INDEX IF NOT EXISTS b2b_companies_name_idx ON public.b2b_companies (name); CREATE INDEX IF NOT EXISTS b2b_companies_industry_idx ON public.b2b_companies (industry);  -- 3. Create b2b_unlocked_leads table CREATE TABLE IF NOT EXISTS public.b2b_unlocked_leads (     id UUID DEFAULT gen_random_uuid() PRIMARY KEY,     user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,     company_id UUID NOT NULL REFERENCES public.b2b_companies(id) ON DELETE CASCADE,     unlocked_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(user_id, company_id) );  -- RLS for b2b_companies (everyone can read for searching, but full details might be hidden in API layer until unlocked) ALTER TABLE public.b2b_companies ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can search b2b_companies" ON public.b2b_companies     FOR SELECT USING (true);  -- Admin can manage b2b_companies CREATE POLICY "Admins can manage b2b_companies" ON public.b2b_companies     USING (         EXISTS (             SELECT 1 FROM public.profiles             WHERE profiles.id = auth.uid() AND profiles.role = 'admin'         )     );  -- RLS for b2b_unlocked_leads ALTER TABLE public.b2b_unlocked_leads ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can View their own unlocked leads" ON public.b2b_unlocked_leads     FOR SELECT USING (auth.uid() = user_id);  CREATE POLICY "Users can insert their own unlocked leads" ON public.b2b_unlocked_leads     FOR INSERT WITH CHECK (auth.uid() = user_id);  -- Insert dummy seed data for testing if table is empty DO $$ BEGIN     IF NOT EXISTS (SELECT 1 FROM public.b2b_companies) THEN         INSERT INTO public.b2b_companies          (name, domain, description, hq_location, industry, size, company_type, keywords, founded_year, technologies, funding_amount)         VALUES          ('Acme Corp', 'acme.com', 'Leading manufacturer of road runner traps.', 'New York, USA', 'Manufacturing', '51-200', 'Private', ARRAY['hardware', 'b2b'], 1990, ARRAY['react', 'node'], '$10M'),         ('TechNova', 'technova.io', 'Innovative cloud solutions for startups.', 'San Francisco, USA', 'Technology', '11-50', 'Startup', ARRAY['saas', 'cloud', 'ai'], 2021, ARRAY['aws', 'python'], '$2M'),         ('Global Finance', 'globalfinance.net', 'Investment banking and asset management.', 'London, UK', 'Finance', '1001-5000', 'Public', ARRAY['finance', 'banking'], 1950, ARRAY['java', 'oracle'], '$1B'),         ('EcoEnergy', 'ecoenergy.org', 'Renewable energy research and development.', 'Berlin, Germany', 'Energy', '201-500', 'Private', ARRAY['green', 'solar'], 2010, ARRAY['go', 'postgres'], '$50M'),         ('HealthPlus', 'healthplus.com', 'Digital healthcare platform.', 'Toronto, Canada', 'Healthcare', '51-200', 'Private', ARRAY['healthtech', 'telemedicine'], 2015, ARRAY['react native', 'graphql'], '$15M'),         ('EduSmart', 'edusmart.edu', 'EdTech solutions for higher education.', 'Boston, USA', 'Education', '11-50', 'Startup', ARRAY['edtech', 'learning'], 2018, ARRAY['vue', 'elixir'], '$5M'),         ('RetailGiant', 'retailgiant.com', 'Global retail chain.', 'Chicago, USA', 'Retail', '10001+', 'Public', ARRAY['ecommerce', 'logistics'], 1980, ARRAY['c#', 'azure'], '$5B'),         ('AgriTech Solutions', 'agritech.co', 'Smart farming technologies.', 'Amsterdam, Netherlands', 'Agriculture', '51-200', 'Private', ARRAY['agritech', 'iot'], 2012, ARRAY['python', 'mqtt'], '$12M'),         ('LogiCorp', 'logicorp.net', 'International logistics and shipping.', 'Singapore', 'Logistics', '501-1000', 'Private', ARRAY['shipping', 'supply chain'], 2000, ARRAY['java', 'spring'], '$100M'),         ('MediaStream', 'mediastream.tv', 'Next-gen streaming services.', 'Los Angeles, USA', 'Media', '201-500', 'Public', ARRAY['streaming', 'video'], 2016, ARRAY['ruby on rails', 'aws'], '$80M');     END IF; END $$;   -- FILE: 20240228_lead_groups.sql  -- Migration: Create lead_groups table and link to leads -- Date: 2024-02-28  -- 1. Create lead_groups table CREATE TABLE IF NOT EXISTS public.lead_groups (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     name TEXT NOT NULL,     description TEXT,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  -- Enable RLS for lead_groups ALTER TABLE public.lead_groups ENABLE ROW LEVEL SECURITY;  -- Creating policies for lead_groups based on account_id CREATE POLICY "Users can view lead groups of their account"     ON public.lead_groups FOR SELECT     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can insert lead groups to their account"     ON public.lead_groups FOR INSERT     WITH CHECK (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can update lead groups of their account"     ON public.lead_groups FOR UPDATE     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can delete lead groups of their account"     ON public.lead_groups FOR DELETE     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  -- 2. Add group_id to leads table ALTER TABLE public.leads  ADD COLUMN IF NOT EXISTS group_id UUID REFERENCES public.lead_groups(id) ON DELETE SET NULL;  -- 3. Create indices for performance CREATE INDEX IF NOT EXISTS idx_lead_groups_account_id ON public.lead_groups(account_id); CREATE INDEX IF NOT EXISTS idx_leads_group_id ON public.leads(group_id);  -- Optional: trigger to automatically update updated_at on lead_groups CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN     NEW.updated_at = NOW();     RETURN NEW; END; $$ language 'plpgsql';  DROP TRIGGER IF EXISTS update_lead_groups_updated_at ON public.lead_groups; CREATE TRIGGER update_lead_groups_updated_at     BEFORE UPDATE ON public.lead_groups     FOR EACH ROW     EXECUTE FUNCTION update_updated_at_column();   -- FILE: 20240301_lead_folders.sql  -- Migration: Create lead_folders table and link to lead_groups -- Date: 2024-03-01  -- 1. Create lead_folders table CREATE TABLE IF NOT EXISTS public.lead_folders (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     name TEXT NOT NULL,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  -- Enable RLS for lead_folders ALTER TABLE public.lead_folders ENABLE ROW LEVEL SECURITY;  -- Creating policies for lead_folders based on account_id CREATE POLICY "Users can view lead folders of their account"     ON public.lead_folders FOR SELECT     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can insert lead folders to their account"     ON public.lead_folders FOR INSERT     WITH CHECK (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can update lead folders of their account"     ON public.lead_folders FOR UPDATE     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  CREATE POLICY "Users can delete lead folders of their account"     ON public.lead_folders FOR DELETE     USING (         account_id IN (             SELECT account_id FROM public.profiles WHERE id = auth.uid()         )     );  -- 2. Add folder_id to lead_groups table ALTER TABLE public.lead_groups  ADD COLUMN IF NOT EXISTS folder_id UUID REFERENCES public.lead_folders(id) ON DELETE SET NULL;  -- 3. Create indices for performance CREATE INDEX IF NOT EXISTS idx_lead_folders_account_id ON public.lead_folders(account_id); CREATE INDEX IF NOT EXISTS idx_lead_groups_folder_id ON public.lead_groups(folder_id);  -- 4. Trigger to automatically update updated_at on lead_folders CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN     NEW.updated_at = NOW();     RETURN NEW; END; $$ language 'plpgsql';  DROP TRIGGER IF EXISTS update_lead_folders_updated_at ON public.lead_folders; CREATE TRIGGER update_lead_folders_updated_at     BEFORE UPDATE ON public.lead_folders     FOR EACH ROW     EXECUTE FUNCTION update_updated_at_column();   -- FILE: 20240314000000_add_is_ai_active.sql  ALTER TABLE conversations ADD COLUMN is_ai_active BOOLEAN DEFAULT TRUE;   -- FILE: 20240318_create_event_logs.sql  -- Migration: Create event_logs table for Activity Log -- Date: 2024-03-18  CREATE TABLE IF NOT EXISTS public.event_logs (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,     event_type TEXT NOT NULL,     entity_type TEXT NOT NULL,     entity_id TEXT,     data JSONB DEFAULT '{}'::jsonb,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  -- Enable RLS ALTER TABLE public.event_logs ENABLE ROW LEVEL SECURITY;  -- RLS Policies CREATE POLICY "Users can view event logs of their account" ON public.event_logs FOR SELECT USING (     account_id IN (         SELECT account_id FROM public.profiles WHERE id = auth.uid()     ) );  -- Index for performance CREATE INDEX IF NOT EXISTS idx_event_logs_account_id ON public.event_logs(account_id); CREATE INDEX IF NOT EXISTS idx_event_logs_created_at ON public.event_logs(created_at);   -- FILE: 20240322_support_tickets_fix.sql  -- Support Tickets Role Consistency Fix -- Ensure admins can view all tickets regardless of tenant isolation  -- Add policy for platform admins to view all profiles (used by joins) DROP POLICY IF EXISTS "Platform Admins can view all profiles" ON public.profiles; CREATE POLICY "Platform Admins can view all profiles" ON public.profiles FOR SELECT USING (     (id = auth.uid()) -- Own profile     OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin' -- Admin access     OR (auth.jwt() ->> 'email' = 'admin@admin.com') -- Special admin access );  -- Update tickets policies DROP POLICY IF EXISTS "Users can view their own tickets" ON public.tickets; CREATE POLICY "Users can view their own tickets" ON public.tickets FOR SELECT USING (     auth.uid() = user_id      OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin'     OR (auth.jwt() ->> 'email' = 'admin@admin.com') );  -- Update ticket messages (admin can view everything) DROP POLICY IF EXISTS "Users can view messages for their tickets" ON public.ticket_messages; CREATE POLICY "Users can view messages for their tickets" ON public.ticket_messages FOR SELECT USING (     EXISTS (         SELECT 1 FROM public.tickets         WHERE tickets.id = ticket_messages.ticket_id         AND (             tickets.user_id = auth.uid()              OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin'             OR (auth.jwt() ->> 'email' = 'admin@admin.com')         )     ) );  -- Update insert policies for admin replies DROP POLICY IF EXISTS "Users can insert messages to their own tickets" ON public.ticket_messages; CREATE POLICY "Users can insert messages to their own tickets" ON public.ticket_messages FOR INSERT WITH CHECK (     EXISTS (         SELECT 1 FROM public.tickets         WHERE tickets.id = ticket_id         AND (             tickets.user_id = auth.uid()              OR (SELECT role FROM public.profiles WHERE id = auth.uid()) = 'admin'             OR (auth.jwt() ->> 'email' = 'admin@admin.com')         )     ) );   -- FILE: 20240323_create_error_logs.sql  -- Create error_logs table for system monitoring CREATE TABLE IF NOT EXISTS public.error_logs (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     created_at TIMESTAMPTZ DEFAULT now(),     message TEXT NOT NULL,     level TEXT DEFAULT 'error',     stack TEXT,     context JSONB,     account_id UUID REFERENCES public.accounts(id) ON DELETE SET NULL,     user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,     path TEXT,     method TEXT,     status_code INTEGER );  -- RLS Policies ALTER TABLE public.error_logs ENABLE ROW LEVEL SECURITY;  -- Only admins can see error logs CREATE POLICY "Admins can see all error logs" ON public.error_logs FOR SELECT USING (     EXISTS (         SELECT 1 FROM public.profiles         WHERE profiles.id = auth.uid()         AND (profiles.role = 'admin' OR profiles.id = '98e097cf-e023-4403-b48d-5c6e1697cebd'::uuid)     ) );  -- Anyone can insert error logs (to allow logging from various parts of the app) CREATE POLICY "Anyone can insert error logs" ON public.error_logs FOR INSERT WITH CHECK (true);  -- Indices CREATE INDEX IF NOT EXISTS error_logs_created_at_idx ON public.error_logs (created_at DESC); CREATE INDEX IF NOT EXISTS error_logs_account_id_idx ON public.error_logs (account_id);
